def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of `equation_v0`."""
    a1, a2, a3, a4, a5, a6 = parameters

    return a1 + a2 * gate_voltage_abs + a3 * drain_voltage_abs + a4 * gate_voltage_abs * drain_voltage_abs + a5 * (gate_voltage_abs * gate_voltage_abs) + a6 * (drain_voltage_abs * drain_voltage_abs)
